Here is a clean Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod
from typing import List, MutableSequence, TypeVar

T = TypeVar('T')

class SortAlgorithm(ABC):
    """Template Method skeleton"""
    def sort(self, data: MutableSequence[T]) -> MutableSequence[T]:
        # template method - final
        self._pre_sort(data)
        self._do_sort(data)
        self._post_sort(data)
        return data

    def _pre_sort(self, data: MutableSequence[T]) -> None:
        pass

    def _post_sort(self, data: MutableSequence[T]) -> None:
        pass

    @abstractmethod
    def _do_sort(self, data: MutableSequence[T]) -> None:
        """Primitive operation - must be implemented by concrete algorithm"""
        ...

    @abstractmethod
    def compare(self, a: T, b: T) -> int:
        """Return -1 if a<b, 0 if a==b, 1 if a>b"""
        ...

    @abstractmethod
    def swap(self, data: MutableSequence[T], i: int, j: int) -> None:
        """Swap two elements"""
        ...


class ArraySortAlgorithm(SortAlgorithm):
    """Common compare/swap for list elements"""
    def compare(self, a: T, b: T) -> int:
        return (a > b) - (a < b)

    def swap(self, data: MutableSequence[T], i: int, j: int) -> None:
        data[i], data[j] = data[j], data[i]


class BubbleSort(ArraySortAlgorithm):
    def _do_sort(self, data: MutableSequence[T]) -> None:
        n = len(data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]) > 0:
                    self.swap(data, j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(ArraySortAlgorithm):
    def _do_sort(self, data: MutableSequence[T]) -> None:
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data[j], data[min_idx]) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(data, i, min_idx)


# Test
if __name__ == "__main__":
    ints = [5, 2, 9, 1, 5, 6]
    strs = ["banana", "apple", "cherry"]

    for Algo in [BubbleSort, SelectionSort]:
        a = Algo()
        data_int = ints.copy()
        a.sort(data_int)
        print(f"{Algo.__name__} ints: {data_int}")

        a2 = Algo()
        data_str = strs.copy()
        a2.sort(data_str)
        print(f"{Algo.__name__} strs: {data_str}")
```

`SortAlgorithm.sort` is the Template Method. It defines the skeleton and delegates the algorithm-specific steps to `_do_sort`, while `compare` and `swap` are the primitive operations used by all concrete sorts. `BubbleSort` and `SelectionSort` provide their own `_do_sort` implementations and reuse the common compare/swap.
